 ['releases_list.png','gallery.release'],['project_calender_page.png','gallery.planning'],['meetings_calender_page.png','gallery.meetings'],['whiteBoards_edit_create_page.png','gallery.whiteboards'],['drive_list_page.png','gallery.drive'],['chat_page.png','gallery.collaboration'],['timeTracker_page.png','gallery.time'],['branding_page.png','gallery.branding'],['theme_page.png','gallery.themes'],['report_page.png','gallery.reporting']
