const required=[...document.querySelectorAll('[data-i18n]')].map(x=>x.dataset.i18n);
for(const [lang,dict] of Object.entries(T)){const missing=required.filter(k=>!(k in dict));if(missing.length)console.warn(`Missing translations for ${lang}:`,missing)}
let lang=localStorage.getItem('asendra-lang')||'en'; if(!T[lang])lang='en';
let theme=localStorage.getItem('asendra-theme')||'dark'; if(!['dark','light'].includes(theme))theme='dark';
const $=s=>document.querySelector(s);
function applyLang(){
 document.documentElement.lang=lang;
 $('#langValue').textContent=lang.toUpperCase();
 document.querySelectorAll('[data-i18n]').forEach(el=>{
   const v=T[lang][el.dataset.i18n];
   if(v!==undefined){
     const attr=el.dataset.i18nAttr;
     if(attr) el.setAttribute(attr,v); else el.textContent=v;
   }
 });
 document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const v=T[lang][el.dataset.i18nPlaceholder];if(v!==undefined)el.placeholder=v});
 localStorage.setItem('asendra-lang',lang);
 const titles={en:'Asendra Chauhan — Full-Stack / Product Engineer',hi:'Asendra Chauhan — फुल-स्टैक / प्रोडक्ट इंजीनियर',es:'Asendra Chauhan — Ingeniero Full-Stack / Producto',fr:'Asendra Chauhan — Ingénieur Full-Stack / Produit',de:'Asendra Chauhan — Full-Stack / Product Engineer',ja:'Asendra Chauhan — フルスタック / プロダクトエンジニア'};
 document.title=titles[lang]||titles.en;
 if($('#gallery') && !$('#gallery').hidden) renderGallery();
}
function applyTheme(){document.documentElement.dataset.theme=theme;$('#themeIcon').textContent=theme==='dark'?'☾':'☀';$('#themeBtn').setAttribute('aria-label',theme==='dark'?'Switch to light theme':'Switch to dark theme');localStorage.setItem('asendra-theme',theme);document.querySelector('meta[name="theme-color"]').setAttribute('content',theme==='dark'?'#090b0b':'#f3f0e7')}
function renderGallery(){const g=$('#gallery');g.innerHTML='';gallery.forEach(([file,key])=>{const title=T[lang][key]||T.en[key];const fig=document.createElement('figure');fig.className='gallery-item reveal visible';fig.innerHTML=`<button type="button" class="gallery-open" aria-label="${title}"><img src="assets/kitesuite/${file}" alt="KiteSuite — ${title}" loading="lazy"><span class="gallery-caption">${title}</span></button>`;g.appendChild(fig)});g.querySelectorAll('.gallery-open').forEach(b=>b.addEventListener('click',()=>openLightbox(b.querySelector('img'))))}
function openLightbox(img){const box=$('#lightbox');$('#lightboxImage').src=img.currentSrc||img.src;$('#lightboxImage').alt=img.alt;$('#lightboxCaption').textContent=img.alt;box.hidden=false;box.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');$('#lightboxClose').focus()}
function closeLightbox(){const box=$('#lightbox');box.hidden=true;box.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
applyLang();applyTheme();
$('#themeBtn').addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';applyTheme()});
$('#langBtn').addEventListener('click',()=>{const m=$('#langMenu');m.hidden=!m.hidden;$('#langBtn').setAttribute('aria-expanded',String(!m.hidden))});
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;applyLang();$('#langMenu').hidden=true;$('#langBtn').setAttribute('aria-expanded','false')}));
$('#menuBtn').addEventListener('click',()=>{const m=$('#mobileMenu');m.hidden=!m.hidden;$('#menuBtn').setAttribute('aria-expanded',String(!m.hidden))});
document.querySelectorAll('.mobile-menu a').forEach(a=>a.addEventListener('click',()=>{$('#mobileMenu').hidden=true;$('#menuBtn').setAttribute('aria-expanded','false')}));
document.addEventListener('click',e=>{if(!e.target.closest('#langBtn')&&!e.target.closest('#langMenu')){$('#langMenu').hidden=true;$('#langBtn').setAttribute('aria-expanded','false')}});
const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.1});document.querySelectorAll('.reveal').forEach(x=>io.observe(x));
addEventListener('scroll',()=>{const h=document.documentElement;$('.scroll-progress').style.width=`${Math.min(100,scrollY/(h.scrollHeight-innerHeight)*100)}%`},{passive:true});
const focusMap={surface:'surface',api:'api',data:'data',ai:'ai',integrations:'integrations',production:'production'};document.querySelectorAll('.map-node').forEach(n=>n.addEventListener('click',()=>{document.querySelectorAll('.map-node').forEach(x=>x.classList.remove('active'));n.classList.add('active');document.querySelectorAll('.layer-card').forEach(x=>x.classList.remove('active'));const target=document.querySelector(`[data-layer="${focusMap[n.dataset.focus]}"]`);if(target){target.classList.add('active');target.scrollIntoView({behavior:'smooth',block:'center'})}}));
$('#galleryBtn').addEventListener('click',()=>{const g=$('#gallery');g.hidden=!g.hidden;if(!g.hidden)renderGallery();});
$('#lightboxClose').addEventListener('click',closeLightbox);
$('#lightbox').addEventListener('click',e=>{if(e.target.id==='lightbox')closeLightbox()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeLightbox();$('#langMenu').hidden=true;$('#mobileMenu').hidden=true}});
const sectionLinks=[...document.querySelectorAll('.desktop-nav a')];const sectionObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){sectionLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${e.target.id}`))}}),{rootMargin:'-35% 0px -55%'});document.querySelectorAll('main section[id]').forEach(s=>sectionObserver.observe(s));
$('#contactForm').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;const d=new FormData(f);const name=(d.get('name')||'').trim(),email=(d.get('email')||'').trim(),message=(d.get('message')||'').trim(),status=$('#formStatus');if(!name||!message||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){status.textContent=T[lang]['form.invalid'];return}const subject=encodeURIComponent(`Portfolio enquiry from ${name}`),body=encodeURIComponent(`Name: ${name}\nEmail: ${email}\n\n${message}`);window.location.href=`mailto:asendrachauhan176@gmail.com?subject=${subject}&body=${body}`;status.textContent=T[lang]['form.success'];});
$('#year').textContent=new Date().getFullYear();
